fn first_even_odd_indices(lst: Vec<i32>) -> (usize, usize) {
    // According to the problem:
    // - i is the index of the first even element, with all elements before it odd
    // - j is the index of the first odd element, with all elements before it even
    //
    // We need to find the smallest index i >= 0 such that lst[i] is even,
    // and for every k < i, lst[k] is odd.
    //
    // Similarly, find the smallest index j >= 0 such that lst[j] is odd,
    // and for every k < j, lst[k] is even.
    //
    // The input guarantees at least one even and one odd number,
    // so both indices must exist.

    // Find i (smallest index where lst[i] even and all previous odd)
    let mut i = None;
    for (idx, &val) in lst.iter().enumerate() {
        if val % 2 == 0 {
            // Check all previous elements are odd
            if lst[..idx].iter().all(|x| x % 2 != 0) {
                i = Some(idx);
                break;
            }
        }
    }

    // Find j (smallest index where lst[j] odd and all previous even)
    let mut j = None;
    for (idx, &val) in lst.iter().enumerate() {
        if val % 2 != 0 {
            // Check all previous elements are even
            if lst[..idx].iter().all(|x| x % 2 == 0) {
                j = Some(idx);
                break;
            }
        }
    }

    // Since the problem guarantees both exist, unwrap is safe
    (i.unwrap(), j.unwrap())
}